WITH RecentInventory AS (SELECT * FROM inventory WHERE last_restock BETWEEN '2023-04-10' AND '2025-05-01' AND quantity BETWEEN 159 AND 200), InventoryStats AS (SELECT product_id, DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, MAX(last_restock) AS last_last_restock, MIN(last_restock) AS min_last_restock FROM RecentInventory GROUP BY product_id, DATE_FORMAT(last_restock, 'yyyy-MM')) SELECT product_id, last_restock_month, last_last_restock, min_last_restock FROM InventoryStats ORDER BY last_restock_month;
